{"action":"write_file","path":"csv.js","content":"'use strict';

// Splits one line of CSV text into its fields.
function parseLine(line) {
  const fields = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch !== '"') field += ch;
      else if (line[i + 1] === '"') { field += '"'; i++; } else quoted = false;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { fields.push(field); field = ''; } else field += ch;
  }
  if (quoted) throw new SyntaxError('unterminated quote');
  fields.push(field);
  return fields;
}

module.exports = { parseLine };
"}

{"action":"write_file","path":"chunk.js","content":"'use strict';

// Splits an array into consecutive pieces of at most `size` items.
function chunk(items, size) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  if (!Number.isInteger(size) || size < 1) throw new RangeError('size must be an integer of at least 1');
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

module.exports = { chunk };
"}

{"action":"write_file","path":"wrap.js","content":"'use strict';

// Word-wraps text to lines of at most `width` characters (a longer single word keeps its own line).
function wrap(text, width) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  if (!Number.isInteger(width) || width < 1) throw new RangeError('width must be an integer of at least 1');
  const lines = [];
  let line = '';
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line && line.length + 1 + word.length <= width) line += ` ${word}`;
    else {
      if (line) lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  return lines.join('\n');
}

module.exports = { wrap };
