{"action":"write_file","path":"slug.js","content":"'use strict';

// Turns a title into a URL slug.
function slugify(text) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  return text
    .normalize('NFD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };
"}

